  LanguageConfig_AwakerAssistRule_CN = {
    Text = "·При проведении игр, таких как Руины Растворения, Запретное писание, Иллюзорное Вдаль от берегов и Трансцендентное существо, можно выбрать для участия пробуждающее тело помощи в бою одного из Хранителей тайн с взаимным вниманием. \n·Пробуждающее тело помощи в бою должно соответствовать ограничениям царства текущего отряда. Пробуждающее тело, не соответствующее условиям, не сможет участвовать в бою, Страж может вернуться и изменить состав отряда, прежде чем снова участвовать в бою. \n·Некоторые мероприятия могут иметь дополнительные специальные правила помощи в бою, пожалуйста, ознакомьтесь с \"описанием мероприятия\" для получения подробной информации."
