  LanguageConfig_BacktrackWeapon_Rules_CN = {
    Text = "<Title:\"Стопка сброса стека позиций\">\n·Эта операция сбросит все состояния стекинга позиций судьбы, все затраты на материалы будут возвращены.\n·За стекинг, активированный с помощью «циклевого мастера», будет возвращен «циклевый мастер»; за стекинг, активированный ограниченным по времени пробуждением, будет возвращено «Ядро отката судьбы»; за стекинг, активированный другими способами, будет возвращена «Книга ротации».\n<Title:\"Вернуться генезиса\">\n·Эта операция сбросит не только все эффекты «Сброса развития», но и само колесо судьбы.\n·За ограниченное по времени пробуждение, полученное с помощью ограниченного колеса судьбы, будет возвращено «Ядро отката судьбы»; за колеса судьбы, полученные другими способами, будет возвращена «Книга ротации».\n<Title:\"Описание предметов\">\n·Следующие предметы используются в интерфейсе ресурсов.\n·«Циклевый мастер»: может использоваться в качестве материала для стекинга любого SSR колеса судьбы.\n·«Книга ротации»: при использовании можно выбрать 1 колеса судьбы из «Оборот колёс» с SSR.\n·«Ядро отката судьбы»: при использовании можно выбрать 1 колеса судьбы из «Оборот колёс», прошлых событий пробуждения колеса судьбы и текущих событий пробуждения колеса судьбы с SSR."
