  LanguageConfig_DiamondDonateDesc_CN = {
    Text = "Каждая капля источной жидкости, которую вы пожертвовали, бесценна. Она будет использована в исследованиях растоврения и строительстве учебных помещений, становясь частью Мисаг и направляясь вместе с вами в то незабываемое будущее. \nПусть Серебряный Ключ направит нас."
