  LanguageConfig_PVPRankingRuleDesc_CN = {
    Text = "<Title:【Рейтинг очков】>\n·[Преднаборный режим] и [Режим поочерёдного выбора] имеют независимые сезоны и рейтинги сезона, награды за рейтинг сезона будут рассчитываться в конце каждого сезона.\n·Участие хотя бы в одном матче в текущем сезоне позволяет войти в рейтинг соответствующего режима, ранжирование основано на историческом максимуме очков за сезон. Одна победа в текущем сезоне позволяет получить награду по рейтингу сезона при его завершении.\n<Title:【Соотношение рангов】>\n·Звания в битвах ранжируются по очкам, полученным в рейтинге, пропорции следующие:\n     ·Легенда фаз: топ 2%\n     ·Повелитель фаз: 2%~10%\n     ·Мастер: 10%~25%\n     ·Элита фаз: 25%~50%\n     ·Ученик шахматиста: 50%~75%\n     ·Новичок фаз: после 75%\n·Если возникают ситуации с одинаковым количеством очков у других Хранителей тайн, они будут отсортированы по времени входа в рейтинг, но звания и награды будут определяться по наивысшему рангу за эти очки."
