  LanguageConfig_Resonance_Group_Desc_24_CN = {
    Text = "В событии \"Дорога безумия\" укажите одно пробуждённое тело, чтобы вызвать Расщепление его духа и потерю четырёх начальных карт команды, после чего путь вперёд появится и вы получите 3 из 1 Золотая реликвия.\n Вы можете вернуть потерянные карты команды по одной в следующих четырёх событиях \"Фрагменты сознания\", возвращённые карты команды будут сразу обладать уникальной гравировкой <EnsembleKeywords:\"Ансамбль\">."
