  LanguageConfig_TrinketBindRuleDesc_CN = {
    Text = "<Title:Слияние Ковенанта>\n·Хранители теперь могут объединять Ковенанты с Пробуждёнными.\n·На каждую позицию Пробуждённого можно установить 1 Ковенант — всего 6 штук.\n·После слияния основной атрибут Ковенанта на каждой позиции дополнительно увеличивается на 50%.\n·Объединённые Ковенанты не будут отображаться в разделах «Ресурсы — Ковенант» и «Алхимия».\n·В Отряде и при поддержке Пробуждённого, если Ковенант не экипирован вручную, объединённый Ковенант будет экипирован автоматически.\n·Усиление объединённого компонента Ковенанта не изменяет состояние слияния; прирост основного атрибута обновляется в соответствии с состоянием после усиления.\n\n<Title:Отвязка Ковенанта>\n·Чтобы изменить или отменить слияние Ковенанта, необходимо отвязать его на странице слияния Ковенантов.\n·Отвязка одного компонента требует 10 Ковенантов того же типа (позиция не ограничена).\n·При отвязке Ковенанта уже использованные Ковенанты не будут отображаться в списке материалов."
  },
